  bool first;using(var mutex=new Mutex(true,@"Local\CursorAtelier-"+(smoke?Guid.NewGuid().ToString("N"):Environment.UserName),out first)){if(!first){MessageBox.Show("光标工坊已经在运行，请双击系统托盘图标打开窗口。","Cursor Atelier");return 0;}var store=new Store(root);try{StartupService.RepairExistingPath();}catch(Exception startupError){ErrorLog.Record(startupError);}Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);Application.ThreadException+=(o,e)=>{ErrorLog.Record(e.Exception);MessageBox.Show("程序遇到未预期错误，已记录详细信息，将恢复 Windows 默认指针并退出。","光标工坊",MessageBoxButtons.OK,MessageBoxIcon.Error);Application.Exit();};bool running=true;AppDomain.CurrentDomain.ProcessExit+=(o,e)=>{if(running)try{NativeExit.WindowsDefault();}catch(Exception error){ErrorLog.Record(error);}};try{using(var form=new MainForm(store)){form.Shown+=(s,e)=>{form.RestoreLastSkin();if(args.Contains("--tray"))form.Hide();if(smoke){var timer=new System.Windows.Forms.Timer{Interval=400};timer.Tick+=(o,ev)=>{timer.Stop();File.WriteAllText(Path.Combine(root,"runtime-smoke.txt"),store.Pref.Active);form.ExitApplication();timer.Dispose();};timer.Start();}};Application.Run(form);}}finally{try{NativeExit.WindowsDefault();}catch(Exception error){ErrorLog.Record(error);}running=false;mutex.ReleaseMutex();}}return 0;
