 static int Test(string[] args){string root=Path.GetFullPath(args[1]);Directory.CreateDirectory(root);var log=new List<string>();var store=new Store(Path.Combine(root,"data"),false);int validated=0;foreach(var s in store.Pref.Skins){Assert(s.Roles.Count==17,"17 roles");foreach(var p in s.Roles.Values){Native.Validate(p);validated++;}}
  Assert(store.Pref.Skins.Count==Art.Names.Length&&validated==Art.Names.Length*17,"sixteen skins");log.Add("PASS: 54 original skins / 918 native cursor files loaded by Windows.");Assert(store.Pref.Skins.Count(s=>s.Animated)==30,"eight animations");
  foreach(int size in new[]{32,64,96}){var skin=store.Pref.Skins[size==64?4:0];store.EnsureBuiltin(skin,size);foreach(var p in skin.Roles.Values)Native.Validate(p);}log.Add("PASS: 32/48/64/96 px cursor generation and native loading.");
  var original=store.Pref.Skins[4];string zip=Path.Combine(root,"roundtrip.zip");store.Export(original,zip);var imported=store.Import(new[]{zip},48,0,0);Assert(imported.Roles.Count==17&&imported.Animated,"roundtrip all roles");foreach(var r in Store.Roles)Assert(File.ReadAllBytes(original.Roles[r]).SequenceEqual(File.ReadAllBytes(imported.Roles[r])),"byte preservation");log.Add("PASS: ZIP export/import preserves all roles and animation bytes.");
  var png=Path.Combine(root,"image.png");using(var b=Art.Draw(1,"Arrow",80,0,1))b.Save(png);var imageSkin=store.Import(new[]{png},48,3,4);var bytes=File.ReadAllBytes(imageSkin.Roles["Arrow"]);Assert(BitConverter.ToUInt16(bytes,10)==3&&BitConverter.ToUInt16(bytes,12)==4,"hotspot");log.Add("PASS: PNG conversion / explicit hotspot / native CUR validation.");
  string gif=Path.Combine(root,"animated.gif");using(var stream=new MemoryStream())using(var w=new BinaryWriter(stream)){w.Write(System.Text.Encoding.ASCII.GetBytes("GIF89a"));w.Write(new byte[]{1,0,1,0,128,0,0,255,0,0,0,0,255});for(int i=0;i<2;i++){w.Write(new byte[]{33,249,4,0,10,0,0,0,44,0,0,0,0,1,0,1,0,0,2,2,(byte)(i==0?68:76),1,0});}w.Write((byte)59);File.WriteAllBytes(gif,stream.ToArray());}var animatedImage=store.Import(new[]{gif},32,1,2);Assert(animatedImage.Animated,"GIF animation");var ani=File.ReadAllBytes(animatedImage.Roles["Arrow"]);Assert(BitConverter.ToInt32(ani,24)==2,"GIF two frames");log.Add("PASS: two-frame GIF converted to native ANI, animation count preserved.");
  Assert(Store.GuessRole("Minecraft Enchanted Netherite Sword Animated Cursor--pointer--SweezyCursors")=="Hand","sweezy pointer");Assert(Store.GuessRole("Minecraft Enchanted Netherite Sword Animated Cursor--cursor--SweezyCursors")=="Arrow","sweezy cursor");
  if(args.Length>2){var sweezy=store.Import(new[]{args[2]},48,0,0);Assert(sweezy.Roles.Count==2&&sweezy.Roles.ContainsKey("Hand")&&sweezy.Roles["Arrow"].EndsWith(".ani")&&sweezy.Roles["Hand"].EndsWith(".cur"),"real Sweezy pair");log.Add("PASS: real Sweezy Complete Pack / ANI Arrow + CUR Hand detected and loaded.");}
  var attack=Path.Combine(root,"traversal.zip");using(var z=ZipFile.Open(attack,ZipArchiveMode.Create)){var e=z.CreateEntry("../../escape.cur");using(var stream=e.Open()){var b=File.ReadAllBytes(imageSkin.Roles["Arrow"]);stream.Write(b,0,b.Length);}}store.Import(new[]{attack},48,0,0);Assert(!File.Exists(Path.Combine(root,"escape.cur")),"zip traversal");log.Add("PASS: ZIP entry paths cannot escape skin library.");
  string bad=Path.Combine(root,"broken.ani");File.WriteAllText(bad,"not a cursor");int previous=store.Pref.Skins.Count;bool rejected=false;try{store.Import(new[]{bad},48,0,0);}catch{rejected=true;}Assert(rejected&&store.Pref.Skins.Count==previous,"malformed rejected");log.Add("PASS: malformed input rejected without creating a skin.");
  store.Pref.Skins[0].Favorite=true;store.Save();var reload=new Store(store.Root);Assert(reload.Pref.Skins[0].Favorite,"persistence");log.Add("PASS: settings and library survive reload.");
  var clone=store.Clone(store.Pref.Skins[8]);Assert(clone.Builtin==-1&&clone.Roles.Count==17&&clone.Name.Contains("副本"),"editable clone");foreach(var role in Store.Roles)Assert(File.ReadAllBytes(clone.Roles[role]).SequenceEqual(File.ReadAllBytes(store.Pref.Skins[8].Roles[role])),"clone bytes");log.Add("PASS: built-in fun skin duplicated as editable personal skin with original bytes.");
  var chosen=new[]{store.Pref.Skins[0],store.Pref.Skins[8],store.Pref.Skins[12]};chosen[1].Favorite=true;string bundle=Path.Combine(root,"library.zip");store.ExportLibrary(chosen,bundle);int start=store.Pref.Skins.Count;store.Import(new[]{bundle},48,0,0);var restored=store.Pref.Skins.Skip(start).ToList();Assert(restored.Count==3,"library count");for(int i=0;i<3;i++){Assert(restored[i].Name==chosen[i].Name&&restored[i].Favorite==chosen[i].Favorite,"library metadata");foreach(var role in Store.Roles)Assert(File.ReadAllBytes(restored[i].Roles[role]).SequenceEqual(File.ReadAllBytes(chosen[i].Roles[role])),"library bytes");}log.Add("PASS: mixed static/animated library backup restores names, favorites, roles and bytes.");
  string migration=Path.Combine(root,"migration");Directory.CreateDirectory(migration);var legacy=new Preferences{Skins=store.Pref.Skins.Where(s=>s.Builtin>=0&&s.Builtin<8).Concat(new[]{clone}).ToList(),ThemeId="sky",Accent="#A12299"};legacy.Skins[0].Favorite=true;File.WriteAllText(Path.Combine(migration,"settings.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(legacy));var migrated=new Store(migration);Assert(migrated.Pref.Skins.Count==Art.Names.Length+1&&migrated.Pref.Skins[0].Favorite&&migrated.Pref.Skins.Any(s=>s.Id==clone.Id),"upgrade migration");Assert(migrated.Pref.ThemeId=="sky"&&migrated.Pref.Accent=="#A12299","appearance persistence");log.Add("PASS: existing eight-skin library upgrades to 54 without losing favorites or imports.");
  foreach(string theme in Theme.Ids){Theme.Switch(theme,"");Assert(Theme.Contrast(Theme.Text,Theme.Bg)>=4.5,"theme readability");Assert(Theme.Contrast(Theme.OnAccent,Theme.Accent)>=4.5,"button readability");}Theme.Switch("midnight","#FFFFFF");Assert(Theme.Contrast(Theme.OnAccent,Theme.Accent)>=4.5,"custom accent text");Theme.Switch("midnight","");log.Add("PASS: six theme palettes and custom accent maintain readable text contrast.");
  foreach(var skin in store.Pref.Skins.Where(s=>s.Builtin>=8))foreach(int size in new[]{32,48,64,96}){var hotspot=Art.Hotspot(skin.Builtin,"Arrow",size);Assert(hotspot.X==(int)Math.Round(3*size/64f)&&hotspot.Y==(int)Math.Round(3*size/64f),"fun arrow tip hotspot");using(var b=Art.Draw(skin.Builtin,"Arrow",size,0,16)){string testFile=Path.Combine(root,"fun-"+skin.Builtin+"-"+size+(Art.IsAnimated(skin.Builtin)?".ani":".cur"));byte[] cursor=Art.Cur(b,hotspot.X,hotspot.Y);File.WriteAllBytes(testFile,Art.IsAnimated(skin.Builtin)?Art.Ani(new List<byte[]>{cursor},5):cursor);Native.Validate(testFile);}}log.Add("PASS: all fun silhouettes load at four sizes with top-left triangle-tip click hotspots.");
  store.Pref.Hotkeys=false;store.Pref.Tray=false;store.Pref.Rotate=false;using(var main=new MainForm(store)){main.Show();main.ShowCategory("趣味造型");Assert(Descendants(main).OfType<SkinCard>().Count()==Art.Names.Length-8,"fun category");main.ShowCategory("新款皮肤");Assert(Descendants(main).OfType<SkinCard>().Count()==15&&Descendants(main).OfType<SkinCard>().All(card=>card.Skin.Builtin>=39)&&Descendants(main).OfType<SkinCard>().Any(card=>card.Selected),"15 new skin category");main.ShowCategory("最近使用");Assert(!Descendants(main).OfType<SkinCard>().Any(),"empty recents");store.Pref.Sort="名称排序";main.ShowCategory("全部皮肤");var names=Descendants(main).OfType<SkinCard>().Select(c=>c.Skin.Name).ToList();Assert(names.SequenceEqual(names.OrderBy(n=>n)),"name sort");foreach(string theme in Theme.Ids){Theme.Switch(theme,"");Assert(main.BackColor==Theme.Bg,"live main recolor");}Theme.Switch("midnight","");using(var appearance=new AppearanceDialog(store)){appearance.Show();appearance.Controls.OfType<Button>().Where(b=>Convert.ToString(b.Tag)=="palette").ElementAt(1).PerformClick();Assert(main.BackColor==Theme.Palette(1)[0],"live palette click");appearance.Close();Assert(main.BackColor==Theme.Palette(0)[0],"cancel theme rollback");}using(var appearance=new AppearanceDialog(store)){appearance.Show();appearance.Controls.OfType<Button>().Where(b=>Convert.ToString(b.Tag)=="palette").ElementAt(3).PerformClick();appearance.Controls.OfType<Button>().First(b=>b.Text=="保存配色").PerformClick();appearance.Close();Assert(store.Pref.ThemeId=="violet"&&main.BackColor==Theme.Palette(3)[0],"save theme");}using(var about=new AboutDialog()){Assert(about.Controls.OfType<Label>().Any(l=>l.Text.Contains("景同志")&&l.Text.Contains("景同学")),"author contacts");}Theme.Switch("midnight","");main.ExitApplication();}log.Add("PASS: fun/recent categories, name sorting, live theme buttons, cancel rollback, saved appearance and author contacts.");
  var baseline=store.Capture();store.Write("capture-test.json",baseline);var capture=store.Read<Snapshot>("capture-test.json");Assert(capture.Values.Count==19,"snapshot");log.Add("PASS: registry backup captured and serialized (read only; desktop scheme not changed).");
  log.Add("System cursor apply/restore and installer execution require manual acceptance testing on target Windows; not exercised by this test.");File.WriteAllLines(Path.Combine(root,"test-results.txt"),log,System.Text.Encoding.UTF8);return 0;
 }
 static void Assert(bool condition,string text){if(!condition)throw new Exception("Test failed: "+text);}
 static IEnumerable<Control> Descendants(Control root){foreach(Control c in root.Controls){yield return c;foreach(var d in Descendants(c))yield return d;}}
 static void RenderSkins(string path,int first=8,int count=16){using(var b=new Bitmap(1120,Math.Max(650,117+((count+3)/4)*268)))using(var g=Graphics.FromImage(b)){g.Clear(Color.FromArgb(16,21,32));using(var f=Theme.Font(21,FontStyle.Bold))g.DrawString("光标工坊 1.6  /  "+(first==39?"新增 15 款原创造型":(Art.Names.Length-8)+" 款趣味造型")+" · 左上同色三角",f,Brushes.White,30,25);for(int i=first;i<first+count;i++){int x=30+(i-first)%4*275,y=97+(i-first)/4*268;using(var brush=new SolidBrush(Color.FromArgb(27,35,50)))g.FillRectangle(brush,x,y,247,240);using(var icon=Art.Draw(i,"Arrow",144,2,16))g.DrawImage(icon,x+51,y+17);using(var f=Theme.Font(13))g.DrawString(Art.Names[i],f,Brushes.White,x+47,y+174);using(var f=Theme.Font(9))using(var brush=new SolidBrush(Color.FromArgb(155,173,196)))g.DrawString(Art.IsAnimated(i)?"动态 · 三角尖端点击":"静态 · 三角尖端点击",f,brush,x+51,y+207);}b.Save(path);}}
 static int Integration(string directory){Directory.CreateDirectory(directory);var log=new List<string>();var store=new Store(Path.Combine(directory,"integration-data"));var baseline=store.Capture();store.Write("emergency-baseline.json",baseline);try{store.Apply(store.Pref.Skins[4]);var applied=store.Capture();Assert(applied.Values.First(v=>v.Name=="Arrow").Value==store.Pref.Skins[4].Roles["Arrow"],"animated registry apply");log.Add("PASS: animated full scheme applied and Windows refresh succeeded.");store.Apply(store.Pref.Skins[1]);store.Restore(false);Assert(store.Capture().Values.First(v=>v.Name=="Arrow").Value==store.Pref.Skins[4].Roles["Arrow"],"undo");log.Add("PASS: second scheme applied and undo restored animated scheme.");store.Restore(true);Assert(EqualSnapshot(baseline,store.Capture()),"restore original exact");log.Add("PASS: original scheme restored, values/types/presence match baseline.");store.Apply(store.Pref.Skins[12]);Assert(store.Pref.Skins[12].LastUsed>0,"recent usage recorded");store.Restore(true);Assert(EqualSnapshot(baseline,store.Capture()),"fun skin restore");log.Add("PASS: animated fun skin applied, recent usage recorded, original scheme restored.");store.WindowsDefault();Assert(store.Capture().Values.First(v=>v.Name=="Arrow").Value=="","windows default");store.Restore(false);Assert(EqualSnapshot(baseline,store.Capture()),"default undo");log.Add("PASS: Windows default reset and undo preserve original scheme.");}
  finally{store.SetSnapshot(baseline);log.Add("FINALLY: original desktop cursor scheme restored.");File.WriteAllLines(Path.Combine(directory,"integration-results.txt"),log,System.Text.Encoding.UTF8);}return 0;}
 static bool EqualSnapshot(Snapshot a,Snapshot b){return a.Values.All(e=>b.Values.Any(v=>v.Name==e.Name&&v.Value==e.Value&&v.Kind==e.Kind&&v.Exists==e.Exists));}
}
